"""Offline Gaussian acceptance boundaries without GPU/Docker/real data."""
import contextlib
import hashlib
import io
import json
import os
from pathlib import Path
import struct
import tempfile
import unittest

from processing import opensplat_trial as trial


def scene(degree=3, value=0.0, rotation=1.0):
    rest = 3 * ((degree + 1) ** 2 - 1)
    names = trial.PREFIX + [f"f_rest_{i}" for i in range(rest)] + trial.SUFFIX
    header = ("ply\nformat binary_little_endian 1.0\n"
              "comment Generated by opensplat at iteration 2000\n"
              "element vertex 1\n" +
              "".join(f"property float {name}\n" for name in names) + "end_header\n").encode()
    values = [value] * len(names)
    values[-4] = rotation
    return header + struct.pack("<" + "f" * len(names), *values)


class OpenSplatTrialTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.ply = self.root / "scene.ply"

    def inspect(self, data):
        self.ply.write_bytes(data)
        return trial.inspect_trial(self.ply)

    def test_valid_degrees_hash_exact_bytes_and_remain_private(self):
        for degree in range(4):
            data = scene(degree)
            report = self.inspect(data)
            self.assertEqual(report["artifact"]["sha256"], hashlib.sha256(data).hexdigest())
            self.assertEqual(report["artifact"]["sphericalHarmonicsDegree"], degree)
            self.assertFalse(report["viewerReady"])
            self.assertFalse(report["publicationEligible"])
            self.assertEqual(report["coordinates"]["status"], "unknown")
            self.assertEqual(self.ply.read_bytes(), data)

    def test_plain_cloud_wrong_properties_and_encoding_rejected(self):
        for data in (b"ply\nformat ascii 1.0\nelement vertex 1\nend_header\n",
                     scene().replace(b"property float opacity", b"property float density"),
                     scene().replace(b"property float rot_3\n", b"property float rot_2\n"),
                     scene().replace(b"end_header\n", b"element face 0\nend_header\n")):
            with self.assertRaises(trial.TrialError):
                self.inspect(data)

    def test_truncated_trailing_and_zero_count_rejected(self):
        for data in (scene()[:-1], scene() + b"x",
                     scene().replace(b"element vertex 1", b"element vertex 0")):
            with self.assertRaises(trial.TrialError):
                self.inspect(data)

    def test_nonfinite_and_zero_quaternion_rejected(self):
        for value in (float("nan"), float("inf"), -float("inf")):
            with self.assertRaisesRegex(trial.TrialError, "ply_nonfinite"):
                self.inspect(scene(value=value))
        with self.assertRaisesRegex(trial.TrialError, "ply_zero_rotation"):
            self.inspect(scene(rotation=0))

    def test_header_and_vertex_budgets(self):
        for data in (b"ply\n" + b"x" * trial.MAX_HEADER_BYTES,
                     scene().replace(b"element vertex 1", b"element vertex 2000001")):
            with self.assertRaises(trial.TrialError):
                self.inspect(data)

    def test_cli_errors_are_structured_and_do_not_leak_paths(self):
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            status = trial.main(["inspect", str(self.root / "private-missing.ply")])
        self.assertEqual(status, 2)
        report = json.loads(out.getvalue())
        self.assertTrue(report["validationErrors"])
        self.assertNotIn(str(self.root), out.getvalue())

    def test_plan_requires_model_and_fresh_separate_output_without_mutation(self):
        project = self.root / "prepared project"
        (project / "images").mkdir(parents=True)
        sparse = project / "sparse" / "0"
        sparse.mkdir(parents=True)
        output = self.root / "new output"
        with self.assertRaises(trial.TrialError):
            trial.plan_command(project, output)
        for name in ("cameras.bin", "images.bin", "points3D.bin"):
            (sparse / name).write_bytes(b"placeholder")
        plan = trial.plan_command(project, output)
        self.assertEqual(plan["argv"][1], str(project.resolve()))
        self.assertFalse(plan["executesWork"])
        self.assertEqual(plan["inputValidation"], "presence-only")
        self.assertNotIn("--center", plan["argv"])
        self.assertFalse(output.exists())
        for bad in (project, project / "results", self.root):
            with self.assertRaises(trial.TrialError):
                trial.plan_command(project, bad)
        for bad in (0, 30001, True):
            with self.assertRaises(trial.TrialError):
                trial.plan_command(project, output, iterations=bad)

    def test_plan_matches_colmap_dispatch_and_root_precedence(self):
        project = self.root / "project"
        (project / "images").mkdir(parents=True)
        sparse = project / "sparse"
        sparse.mkdir()
        for name in ("cameras.bin", "images.bin", "points3D.bin"):
            (sparse / name).write_bytes(b"placeholder")
        output = self.root / "output"
        # Direct sparse exports are not read by this pinned upstream version.
        with self.assertRaises(trial.TrialError):
            trial.plan_command(project, output)
        zero = sparse / "0"
        zero.mkdir()
        for name in ("cameras.bin", "images.bin", "points3D.bin"):
            (zero / name).write_bytes(b"placeholder")
        trial.plan_command(project, output)
        (project / "transforms.json").write_text("{}")
        with self.assertRaisesRegex(trial.TrialError, "ambiguous_input_format"):
            trial.plan_command(project, output)
        (project / "transforms.json").unlink()
        (project / "cameras.bin").write_bytes(b"placeholder")
        # Root camera wins even when sparse/0 is complete.
        with self.assertRaises(trial.TrialError):
            trial.plan_command(project, output)

    def test_linked_files_and_plan_roots_rejected(self):
        self.ply.write_bytes(scene())
        linked = self.root / "link"
        try:
            os.symlink(self.root, linked, target_is_directory=True)
        except OSError:
            self.skipTest("OS does not permit symlink creation")
        with self.assertRaisesRegex(trial.TrialError, "linked_path"):
            trial.inspect_ply(linked / self.ply.name)
        with self.assertRaisesRegex(trial.TrialError, "linked_path"):
            trial.plan_command(linked, self.root / "output")


if __name__ == "__main__":
    unittest.main()
